/* 输入是闭区间，端点相等也算相交；输出先给结果段数。 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b)  {
    return a < b ? a : b;
}
int mx(int a, int b)  {
    return a > b ? a : b;
}
int read(void)  {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a)  {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x)  {
    printf("%d ", x);
}
void emitstr(int* a, int n)  {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void)  {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int i = 0, j = 0,
    /* 排序必须同时交换左右端点；扫描时只比较新区间与最后结果段。 */
    k = 0, n = 0, x = 0;
    n = read();
    for (i = 0; i < n; i += 1)  {
        a[i] = read();
        b[i] = read();
    }
    for (i = 0; i < n; i += 1)  {
        for (j = (i + 1); j < n; j += 1)  {
            if (a[j] < a[i])  {
                x = a[i];
                a[i] = a[j];
                a[j] = x;
                x = b[i];
                b[i] = b[j];
                b[j] = x;
            }
        }
    }
    k = 0;
    for (i = 0; i < n; i += 1)  {
        if ((k == 0) || (a[i] > e[(k - 1)]))  {
            d[k] = a[i];
            e[k] = b[i];
            k = (k + 1);
        }
        else  {
            e[(k - 1)] = mx(e[(k - 1)], b[i]);
        }
    }
    /* 相交则延伸末段右端点，真正有间隙才新开段，保留全部覆盖范围。 */
    emit(k);
    for (i = 0; i < k; i += 1)  {
        emit(d[i]);
        emit(e[i]);
    }
    return 0;
}

